+			} else {
+				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
+			}
+		case "skip":
+			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
